import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    teacher_logits = torch.randn(3, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(inputs), "teacher_logits": synth.Tensor(teacher_logits)}
dataset = synth.Spec("student-teacher-logits", generator=samples, size=12, splits={"train": 1.0}, seed=13, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class Student(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=3)
    def forward(self, inputs):
        return {"logits": self.network(inputs)}
trainer = Trainer(Student(), train, recipe="structured-objective", recipe_config={"loss": "student-teacher", "loss_kwargs": {"temperature": 2.0}, "bindings": {"logits_or_prediction": {"output": "logits"}, "targets": {"batch": "teacher_logits"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
